const ee = require('@google/earthengine'); 
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a polygon along the Lower Mississippi River encompassing the specified cities.
  // This polygon roughly covers the river from Arkansas City to south of Natchez.
  const geometry = ee.Geometry.Polygon(
    [[[-91.1, 34.0],
      [-90.8, 31.0],
      [-91.3, 31.0],
      [-91.5, 34.0]]]);

  const date1_start = '2017-03-12'; // March 19, 2017 +/- 7 days
  const date1_end = '2017-03-26';
  const date2_start = '2019-03-12'; // March 19, 2019 +/- 7 days
  const date2_end = '2019-03-26';

  const polarization = 'VV'; // Vertical transmit/Vertical receive
  const orbitProperties = 'DESCENDING'; // Descending pass for consistency
  const scale = 30; // Sentinel-1 resolution is 10m, but 30m is fine for area calculation over large regions.

  // Function to get and process Sentinel-1 imagery for a given date range
  const getWaterExtent = (startDate, endDate, geom) => {
    let collection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(geom)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', polarization))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', orbitProperties))
      .select(polarization);

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      return { image: null, size: 0, cloud_percentage: 0 };
    }

    // Apply speckle filtering (focal median is a simple approach)
    let image = collection.mosaic().focal_median();

    // Convert to dB scale (if not already, S1 GRD is usually in linear power, so convert to dB)
    // and apply a threshold for water detection. Water appears dark (low backscatter).
    // A common threshold for water is around -18 dB to -15 dB. Let's use -18 dB.
    image = ee.Image.constant(0).where(image.lt(-18), 1); // Water mask where VV < -18 dB

    // Calculate water area in square kilometers
    const waterAreaSqKm = image.multiply(ee.Image.pixelArea())
      .divide(1e6) // Convert m^2 to km^2
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9
      }).get(polarization);

    const waterPixels = image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get(polarization);

    return {
      area: waterAreaSqKm,
      pixels: waterPixels,
      size: collectionSize,
    };
  };

  // 2. Data Acquisition & Check for 2017
  const result2017 = getWaterExtent(date1_start, date1_end, geometry);
  const area2017 = result2017.area.getInfo();
  const pixels2017 = result2017.pixels.getInfo();

  console.log(`2017 Images: ${result2017.size}`);

  if (result2017.size === 0) {
    console.log("No Sentinel-1 data found for 2017.");
    console.log("C1");
    return;
  }
  if (pixels2017 === 0 || pixels2017 === null) {
    console.log("No valid water pixels found for 2017 after processing.");
    console.log("C2");
    return;
  }
  if (area2017 === null || isNaN(area2017)) {
    console.log("2017 Water area calculation failed.");
    console.log("C3");
    return;
  }
  console.log(`2017 Water Area: ${area2017.toFixed(2)} sq km (Pixels: ${pixels2017})`);

  // 2. Data Acquisition & Check for 2019
  const result2019 = getWaterExtent(date2_start, date2_end, geometry);
  const area2019 = result2019.area.getInfo();
  const pixels2019 = result2019.pixels.getInfo();

  console.log(`2019 Images: ${result2019.size}`);

  if (result2019.size === 0) {
    console.log("No Sentinel-1 data found for 2019.");
    console.log("C1");
    return;
  }
  if (pixels2019 === 0 || pixels2019 === null) {
    console.log("No valid water pixels found for 2019 after processing.");
    console.log("C2");
    return;
  }
  if (area2019 === null || isNaN(area2019)) {
    console.log("2019 Water area calculation failed.");
    console.log("C3");
    return;
  }
  console.log(`2019 Water Area: ${area2019.toFixed(2)} sq km (Pixels: ${pixels2019})`);

  // 5. Validation & Final Answer
  if (area2019 > area2017) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
